1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
13	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
14	
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
25	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
26	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
27	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "formatCheckDigit")
28	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "formatMembershipLevel")
29	    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
30	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "formatContactPreference")
31	    @Mapping(target = "bulkSignupWarning", ignore = true)
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * Derives an owner's preferred contact channel for the read-only {@code contactPreference}
36	     * field: {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
37	     */
38	    @Named("formatContactPreference")
39	    default String formatContactPreference(Owner owner) {
40	        if (owner == null) {
41	            return null;
42	        }
43	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
44	        return hasEmail ? "EMAIL" : "PHONE";
45	    }
46	
47	    /**
48	     * Derives an owner's {@code locality} from its region-and-hash customer code: the region is the
49	     * segment of the {@code '<REGION>-<HASH8>'} code before the first {@code '-'}, so the locality
50	     * always agrees with the identity's region (which itself prefers the postcode over the city,
51	     * defaulting to {@code 'UNKNOWN'}). Returns {@code 'UNKNOWN'} when no customer code is present.
52	     */
53	    @Named("formatLocality")
54	    default String formatLocality(Owner owner) {
55	        if (owner == null) {
56	            return null;
57	        }
58	        String code = owner.getCustomerCode();
59	        if (code == null || code.isBlank()) {
60	            return "UNKNOWN";
61	        }
62	        int dash = code.indexOf('-');
63	        return dash < 0 ? code : code.substring(0, dash);
64	    }
65	
66	    /**
67	     * Determines an owner's numeric membership level for the read-only {@code membershipLevel}
68	     * field, assigned at creation and ranging from 1 to 3: it starts at 1, gains 1 when an email
69	     * address is present, gains 1 when the owner had no namesakes at creation (namesakeCount is 0),
70	     * and is capped at 3. Level 4 is reserved for tenure.
71	     */
72	    @Named("formatMembershipLevel")
73	    default Integer formatMembershipLevel(Owner owner) {
74	        if (owner == null) {
75	            return null;
76	        }
77	        int level = 1;
78	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
79	        if (hasEmail) {
80	            level++;
81	        }
82	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
83	        if (noNamesakes) {
84	            level++;
85	        }
86	        return Math.min(level, 3);
87	    }
88	
89	    /**
90	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last
91	     * two digits of the registrationDate year (e.g. {@code 'NSW-1A2B3C4D-M26'}), for the read-only
92	     * {@code membershipNumber} field. Null when the customer code or registration date is absent.
