3	/**
4	 * Normalizes free-form telephone input into canonical E.164 form.
5	 *
6	 * <p>Rules:
7	 * <ul>
8	 *   <li>Spaces, dashes, brackets and any other non-digit separators are stripped.</li>
9	 *   <li>A leading {@code '+'} means the country code is already present and is kept.</li>
10	 *   <li>Otherwise the Australian country code {@code +61} is assumed and a single
11	 *       leading {@code '0'} is dropped from the national digits.</li>
12	 *   <li>The result must carry between 8 and 15 digits after the {@code '+'}, otherwise
13	 *       it cannot form a valid E.164 number.</li>
14	 *   <li>For a recognised country code the national number (the digits after the country
15	 *       code) must have the exact length that country requires: {@code +61} needs 9
16	 *       national digits and {@code +1} needs 10. A wrong national length for the country
17	 *       is rejected.</li>
18	 * </ul>
19	 *
20	 * <p>For example {@code '0412 345 678'} becomes {@code '+61412345678'} and
21	 * {@code '+64 21 123 456'} becomes {@code '+6421123456'}.
22	 */
23	public final class TelephoneNormalizer {
24	
25	    private TelephoneNormalizer() {
26	    }
27	
28	    /**
29	     * Converts raw telephone input to E.164, or returns {@code null} when the input is
30	     * {@code null} or cannot form a valid E.164 number.
31	     *
32	     * @param raw the raw telephone input (may be {@code null})
33	     * @return the E.164 string (e.g. {@code '+61412345678'}), or {@code null}
34	     */
35	    public static String toE164(String raw) {
36	        if (raw == null) {
37	            return null;
38	        }
39	        boolean hasCountryCode = raw.trim().startsWith("+");
40	        String digits = raw.replaceAll("\\D", "");
41	        if (!hasCountryCode) {
42	            if (digits.startsWith("0")) {
43	                digits = digits.substring(1);
44	            }
45	            digits = "61" + digits;
46	        }
47	        if (digits.length() < 8 || digits.length() > 15) {
48	            return null;
49	        }
50	        if (!hasValidNationalLength(digits)) {
51	            return null;
52	        }
53	        return "+" + digits;
54	    }
55	
56	    /**
57	     * Checks the national-number length against the country code carried by {@code digits}
58	     * (the E.164 digits without the leading {@code '+'}). {@code +61} requires 9 national
59	     * digits and {@code +1} requires 10; the national number is whatever follows the
60	     * country code. Country codes without a known length pass this check and are governed
61	     * only by the generic 8-to-15 total-digit rule.
62	     *
63	     * @param digits the E.164 digits without the leading {@code '+'}
64	     * @return {@code true} when the national-number length is acceptable for the country
65	     */
66	    private static boolean hasValidNationalLength(String digits) {
67	        if (digits.startsWith("61")) {
68	            return digits.length() - 2 == 9;
69	        }
70	        if (digits.startsWith("1")) {
71	            return digits.length() - 1 == 10;
72	        }
73	        return true;
74	    }
75	
76	    /**
77	     * @param raw the raw telephone input (may be {@code null})
78	     * @return {@code true} when {@code raw} is {@code null} (absence is handled elsewhere)
79	     *         or can form a valid E.164 number
80	     */
81	    public static boolean isValid(String raw) {
82	        return raw == null || toE164(raw) != null;
83	    }
84	}
